import sys
from collections import defaultdict, deque

def bfs(graph, start):
    queue = deque([start])
    visited = {start: 0}
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited[neighbor] = visited[node] + 1
                queue.append(neighbor)
    return visited

def find_odd_cycle(graph, n):
    for start in range(1, n + 1):
        distances = bfs(graph, start)
        for node in distances:
            if distances[node] % 2 == 1:
                return [start, node]
    return None

def count_ways_to_add_edges(graph, n, m):
    odd_cycle = find_odd_cycle(graph, n)
    if odd_cycle:
        return 0, 1

    # If no odd cycle exists, we need to add at least 3 edges to form a triangle
    return 3, 1

